const express = require('express');
const app = express();

// Middleware to parse JSON bodies
app.use(express.json({ limit: '1mb' }));

// Email validation regex - supports complex subdomains and plus addressing
const EMAIL_REGEX = /^([a-zA-Z0-9]+([.+_-][a-zA-Z0-9]+)*)+@([a-zA-Z0-9]+([.-][a-zA-Z0-9]+)*)+\.[a-zA-Z]{2,}$/;

// URL validation for callback registration
const CALLBACK_URL_REGEX = /^https?:\/\/([a-zA-Z0-9]+(-[a-zA-Z0-9]+)*\.)+[a-zA-Z]{2,}(\/[a-zA-Z0-9._~:/?#\[\]@!$&'()*+,;=-]*)*$/;

// Internal health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', timestamp: Date.now() });
});

// User registration endpoint
app.post('/api/v1/register', (req, res) => {
  const { email, name, callbackUrl } = req.body;

  if (!email || !name) {
    return res.status(400).json({ error: 'email and name are required' });
  }

  // Validate email format
  if (!EMAIL_REGEX.test(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // Validate callback URL if provided
  if (callbackUrl && !CALLBACK_URL_REGEX.test(callbackUrl)) {
    return res.status(400).json({ error: 'Invalid callback URL format' });
  }

  // Simulate registration logic
  const userId = Math.random().toString(36).substring(2, 15);
  res.status(201).json({
    id: userId,
    email: email,
    name: name,
    callbackUrl: callbackUrl || null,
    createdAt: new Date().toISOString()
  });
});

// Webhook subscription endpoint
app.post('/api/v1/webhooks', (req, res) => {
  const { url, events } = req.body;

  if (!url) {
    return res.status(400).json({ error: 'url is required' });
  }

  if (!CALLBACK_URL_REGEX.test(url)) {
    return res.status(400).json({ error: 'Invalid webhook URL' });
  }

  if (!Array.isArray(events) || events.length === 0) {
    return res.status(400).json({ error: 'events must be a non-empty array' });
  }

  res.status(201).json({
    webhookId: Math.random().toString(36).substring(2, 15),
    url: url,
    events: events,
    active: true
  });
});

// Search endpoint with pattern matching
app.get('/api/v1/search', (req, res) => {
  const { pattern } = req.query;

  if (!pattern) {
    return res.status(400).json({ error: 'pattern query parameter is required' });
  }

  // Validate the search pattern isn't malicious
  const SAFE_PATTERN = /^[a-zA-Z0-9 ._-]+$/;
  if (!SAFE_PATTERN.test(pattern)) {
    return res.status(400).json({ error: 'Pattern contains invalid characters' });
  }

  // Simulate search results
  res.json({ results: [], query: pattern });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Service listening on port ${PORT}`);
});

module.exports = app;
